// Dimpled grip on the waist: columns of round dimples, bigger toward the middle rows.
function dimples() {
  // One dotted stroke per column: round caps on zero-length dashes give the dimples.
  let dark = '', light = '';
  for (let j = -5; j <= 5; j++) {
    const a = j * 0.255;
    const x = 100 + 29.8 * Math.sin(a);
    const w = 2.1 * Math.sqrt(Math.cos(a));
    dark += `<path d="M${r2(x + 0.25)} 160.9V200" stroke-width="${r2(w)}"/>`;
    light += `<path d="M${r2(x - 0.3)} 160.25V199.4" stroke-width="${r2(w * 0.45)}"/>`;
  }
  return `<g stroke="#000" opacity=".2" stroke-linecap="round" stroke-dasharray="0 4.1">${dark}</g><g stroke="#fff" opacity=".42" stroke-linecap="round" stroke-dasharray="0 4.1">${light}</g>`;
}
